def split_row(line: str):
    """Split one CSV line into fields.

    Commas inside double-quoted fields are part of the field, and two
    consecutive double quotes inside such a field represent one quote.
    """
    fields = []
    field = []
    in_quotes = False
    i = 0

    while i < len(line):
        char = line[i]

        if char == '"':
            if in_quotes:
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 1
                else:
                    in_quotes = False
            elif not field:
                in_quotes = True
            else:
                field.append(char)
        elif char == ',' and not in_quotes:
            fields.append(''.join(field))
            field = []
        else:
            field.append(char)

        i += 1

    fields.append(''.join(field))
    return fields
